options.customCss:
:root {
  /* --- WhatsApp Brand Palette --- */
  --chat--color--primary: #00a884;               /* WhatsApp Vibrant Teal */
  --chat--color--primary-shade-50: #008f72;      /* Deep Teal Hover */
  --chat--color--primary--shade-100: #00755e;     /* Press/Active Teal */
  --chat--color--secondary: #d9fdd3;             /* WhatsApp Outgoing Bubble Green */
  --chat--color-secondary-shade-50: #cfe9cc;     /* Outgoing Bubble Border/Hover */
  --chat--color-white: #ffffff;
  --chat--color-light: #f0f2f5;                  /* Classic WhatsApp App Background */
  --chat--color-light-shade-50: #eaebeb;          /* Subtle borders and panels */
  --chat--color-light-shade-100: #d1d7db;         /* WhatsApp Divider Gray */
  --chat--color-medium: #8696a0;                 /* WhatsApp Secondary Text Muted Gray */
  --chat--color-dark: #111b21;                   /* WhatsApp Deep Charcoal Dark Text */
  --chat--color-disabled: #bac0c4;
  --chat--color-typing: #00a884;                 /* Active typing matches brand teal */

  /* --- Layout & Typography --- */
  --chat--spacing: 0.875rem;                      /* Tighter chat-optimized layout grid */
  --chat--border-radius: 0.5rem;                  /* Clean UI container rounding */
  --chat--transition-duration: 0.2s;
  --chat--font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;

  /* --- Window Dimensions & Elevation --- */
  --chat--window--width: 380px;
  --chat--window--height: 600px;
  --chat--window--bottom: 20px;
  --chat--window--right: 20px;
  --chat--window--z-index: 9999;
  --chat--window--border: 1px solid var(--chat--color-light-shade-100);
  --chat--window--border-radius: 12px;           /* Modern framing */
  --chat--window--margin-bottom: var(--chat--spacing);
  --chat--window--box-shadow: 0 6px 18px rgba(11, 20, 26, 0.15); /* Soft, real-world depth shadow */

  /* --- WhatsApp Style Header --- */
  --chat--header-height: auto;
  --chat--header--padding: 0.75rem 1rem;
  --chat--header--background: #008069;           /* Core WhatsApp Top Bar Teal */
  --chat--header--color: var(--chat--color-white);
  --chat--header--border-top: none;
  --chat--header--border-bottom: none;
  --chat--header--border-left: none;
  --chat--header--border-right: none;
  --chat--heading--font-size: 1.15rem;           /* Balanced header text size */
  --chat--subtitle--font-size: 0.8rem;
  --chat--subtitle--line-height: 1.3;

  /* --- Message Bubble Dynamics --- */
  --chat--message--font-size: 0.925rem;
  --chat--message--padding: 0.5rem 0.75rem;      /* Native compact text framing */
  --chat--message--border-radius: 8px;           /* Snug message corners */
  --chat--message-line-height: 1.45;
  --chat--message--margin-bottom: 0.5rem;         /* Stacked tightly like true logs */

  /* Incoming (Bot) Bubble Styles */
  --chat--message--bot--background: var(--chat--color-white);
  --chat--message--bot--color: var(--chat--color-dark);
  --chat--message--bot--border: none;

  /* Outgoing (User) Bubble Styles */
  --chat--message--user--background: var(--chat--color--secondary);
  --chat--message--user--color: var(--chat--color-dark); /* Dark text on light green bubble */
  --chat--message--user--border: none;

  --chat--message--pre--background: rgba(0, 0, 0, 0.04);
  --chat--messages-list--padding: 1rem;

  /* --- Floating Launcher Button --- */
  --chat--toggle--size: 52px;
  --chat--toggle--width: var(--chat--toggle--size);
  --chat--toggle--height: var(--chat--toggle--size);
  --chat--toggle--border-radius: 50%;
  --chat--toggle--background: var(--chat--color--primary);
  --chat--toggle--hover--background: var(--chat--color--primary-shade-50);
  --chat--toggle--active--background: var(--chat--color--primary--shade-100);
  --chat--toggle--color: var(--chat--color-white);
  --chat--toggle--box-shadow: 0 4px 10px rgba(0, 168, 132, 0.3);

  /* --- Input Area Bar --- */
  --chat--textarea--height: auto;
  --chat--textarea--max-height: 8rem;
  --chat--input--font-size: 0.95rem;
  --chat--input--border: 1px solid var(--chat--color-white);
  --chat--input--border-radius: 20px;            /* Pill shaped text field input */
  --chat--input--padding: 0.5rem 1rem;
  --chat--input--background: var(--chat--color-white);
  --chat--input--text-color: var(--chat--color-dark);
  --chat--input--line-height: 1.4;
  --chat--input--placeholder--font-size: var(--chat--input--font-size);
  --chat--input--border-active: 1px solid var(--chat--color-light-shade-100);
  --chat--input--left--panel--width: 2rem;

  /* --- System Dialog Buttons --- */
  --chat--button--padding: 0.5rem 1rem;
  --chat--button--border-radius: 20px;
  --chat--button--font-size: 0.85rem;
  --chat--button--line-height: 1.2;
  --chat--button--color--primary: var(--chat--color-white);
  --chat--button--background--primary: var(--chat--color--primary);
  --chat--button--border--primary: none;
  --chat--button--color--primary--hover: var(--chat--color-white);
  --chat--button--background--primary--hover: var(--chat--color--primary-shade-50);
  --chat--button--border--primary--hover: none;
  --chat--button--color--primary--disabled: var(--chat--color-white);
  --chat--button--background--primary--disabled: var(--chat--color-disabled);
  --chat--button--border--primary--disabled: none;

  --chat--button--color--secondary: var(--chat--color-dark);
  --chat--button--background--secondary: var(--chat--color-light-shade-50);
  --chat--button--border--secondary: none;
  --chat--button--color--secondary--hover: var(--chat--color-dark);
  --chat--button--background--secondary--hover: var(--chat--color-light-shade-100);
  --chat--button--border--secondary--hover: none;
  --chat--button--color--secondary--disabled: var(--chat--color-disabled);
  --chat--button--background--secondary--disabled: var(--chat--color-light);
  --chat--button--border--secondary--disabled: none;
  --chat--close--button--color-hover: var(--chat--color--primary);

  /* --- Action Icons Interaction --- */
  --chat--input--send--button--background: transparent;
  --chat--input--send--button--color: var(--chat--color--primary);
  --chat--input--send--button--background-hover: transparent;
  --chat--input--send--button--color-hover: var(--chat--color--primary-shade-50);
  --chat--input--file--button--background: transparent;
  --chat--input--file--button--color: var(--chat--color-medium);
  --chat--input--file--button--background-hover: transparent;
  --chat--input--file--button--color-hover: var(--chat--color-dark);
  --chat--files-spacing: 0.35rem;

  /* --- Background & Canvas Panels --- */
  --chat--body--background: #efeae2;             /* WhatsApp Subtle Beige Matte Base Canvas */
  --chat--footer--background: var(--chat--color-light); /* Off-white bottom keyboard tray */
  --chat--footer--color: var(--chat--color-dark);
}

/* --- Strict Production Custom Overrides --- */

/* Message Bubble Alignment Layout styling */
.chat-message {
  max-width: 82%; 
  box-shadow: 0 1px 0.5px rgba(11, 20, 26, 0.08); /* Native flat card bubble shadow */
  position: relative;
}

/* Distinct WhatsApp Rounded Tail Styling Variants */
.chat-message.bot {
  border-top-left-radius: 0px !important;       /* Corner accent for message chains */
}

.chat-message.user {
  border-top-right-radius: 0px !important;      /* Corner accent for user response */
}

/* Optional Custom Scrollbar formatting for pure sleek finish */
.chat-messages-list::-webkit-scrollbar {
  width: 6px;
}
.chat-messages-list::-webkit-scrollbar-thumb {
  background-color: rgba(11, 20, 26, 0.2);
  border-radius: 3px;
}
